(function(global){
 'use strict';
 const defaults=Object.freeze({autoRest:true,compactCompleted:true,feedbackSymbol:true,duplicateVideoWarning:true});
 function read(){const result={};for(const [key,value]of Object.entries(defaults))result[key]=typeof state.teacherFeatures?.[key]==='boolean'?state.teacherFeatures[key]:value;return result}
 function set(name,value){
  if(!Object.hasOwn(defaults,name)||typeof value!=='boolean')throw Error('Opção inválida.');
  if(global.parent?.APaccounts?.isTeacher?.()!==true||global.parent.__AP_STUDENT_CONTEXT)throw Error('Entre como professor para alterar as funções.');
  const config={...(state.teacherFeatures&&typeof state.teacherFeatures==='object'?state.teacherFeatures:{}),version:1,...read(),[name]:value};
  try{localStorage.setItem(DB_KEY,JSON.stringify({...state,teacherFeatures:config}))}catch(_){throw Error('Não foi possível salvar. A configuração anterior foi mantida.')}
  state.teacherFeatures=config;
  try{if(['autoRest','compactCompleted'].includes(name))global.APWorkoutCorrections?.decorate()}catch(_){}
  try{if(name==='duplicateVideoWarning')global.APVideoDuplicateUI?.refresh()}catch(_){}
  try{global.APTeacherSync?.changed()}catch(_){}
  return read();
 }
 global.APTeacherFeatures=Object.freeze({read,set,enabled:name=>read()[name]!==false});
})(window);

(function () {
  'use strict';

  function initializeRegistrationNotices() {
    const bell = document.querySelector('.header-notifications');
    const notices = document.querySelector('#screen-notices .module-heading');
    const registration = window.agendaRegistration;
    if (!bell || !notices || !registration) return;

    const accounts = window.parent?.APaccounts;
    if (!accounts?.registrationSdk || accounts.isTeacher?.() !== true) return;

    const style = document.createElement('style');
    style.textContent = ".header-notifications[data-registration-pending] .notification-dot {\n  display: none;\n}\n.registration-notification-count {\n  position: absolute;\n  inset-block-start: -3px;\n  inset-inline-end: -4px;\n  min-width: 18px;\n  padding: 0 4px;\n  border-radius: 999px;\n  border: 1px solid var(--ac-surface, #191521);\n  background: #6425a0;\n  color: #fff;\n  font: 700 10px/16px system-ui, sans-serif;\n  text-align: center;\n  pointer-events: none;\n}\n.registration-notification-card {\n  display: grid;\n  justify-items: start;\n  gap: 10px;\n}\n.registration-notification-count[hidden],\n.registration-notification-card[hidden] {\n  display: none;\n}\n";
    document.head.append(style);

    const teacherUid = registration.teacher;
    const originalLabel = bell.getAttribute('aria-label') || 'Abrir avisos e atualizações';
    const badge = document.createElement('span');
    badge.className = 'registration-notification-count';
    badge.setAttribute('aria-hidden', 'true');
    badge.hidden = true;
    bell.append(badge);

    const card = document.createElement('article');
    card.className = 'notice-update registration-notification-card';
    card.hidden = true;
    const title = document.createElement('h3');
    title.setAttribute('role', 'status');
    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'btn';
    open.textContent = 'Ver cadastros';
    open.onclick = () => {
      window.openRegistrationLink();
      window.setRegistrationTab('contacts');
    };
    card.append(title, open);
    notices.after(card);

    let pendingIds = [];
    let sdk, stopAuth, stopPending;
    let connecting = false;
    let closed = false;

    function render() {
      const count = pendingIds.filter(uid => !state.registrationContactsHidden?.[teacherUid + ':' + uid]).length;
      const label = count === 1 ? '1 aluno aguardando aprovação' : count + ' alunos aguardando aprovação';
      badge.textContent = count > 99 ? '99+' : String(count);
      badge.hidden = card.hidden = count === 0;
      title.textContent = count ? label : '';
      bell.toggleAttribute('data-registration-pending', count > 0);
      bell.setAttribute('aria-label', count ? originalLabel + '. ' + label : originalLabel);
    }

    function resetPending() {
      stopPending?.();
      stopPending = null;
      pendingIds = [];
      render();
    }

    function listen() {
      if (closed || !sdk) return;
      if (sdk.auth.currentUser?.uid !== teacherUid) {
        resetPending();
        return;
      }
      if (stopPending) return;

      const filters = sdk.query(sdk.collection(sdk.db, 'usuarios'),
        sdk.where('professorId', '==', teacherUid),
        sdk.where('perfil', '==', 'aluno'),
        sdk.where('ativo', '==', false));
      stopPending = sdk.onSnapshot(filters, snapshot => {
        if (closed || sdk.auth.currentUser?.uid !== teacherUid) return;
        pendingIds = snapshot.docs.map(doc => doc.id);
        render();
      }, error => {
        resetPending();
        console.warn('Não foi possível acompanhar novos cadastros.', error.code || error.message);
      });
    }

    async function start() {
      if (closed || connecting) return;
      if (sdk) {
        listen();
        return;
      }
      connecting = true;
      try {
        sdk = await accounts.registrationSdk();
        if (!closed) stopAuth = sdk.onAuthStateChanged(sdk.auth, listen);
      } catch (error) {
        console.warn('Cadastro online indisponível no sininho.', error.code || error.message);
      } finally {
        connecting = false;
      }
    }

    // The Contacts list updates local exclusions independently of Firestore.
    const contacts = document.getElementById('registrationContactsView');
    if (contacts) new MutationObserver(render).observe(contacts, { childList: true, subtree: true });
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) {
        render();
        void start();
      }
    });
    window.addEventListener('online', start);
    window.addEventListener('pagehide', () => {
      closed = true;
      stopAuth?.();
      stopAuth = null;
      resetPending();
    });
    window.addEventListener('pageshow', event => {
      if (!event.persisted) return;
      closed = false;
      sdk = null;
      void start();
    });
    void start();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeRegistrationNotices, { once: true });
  } else {
    initializeRegistrationNotices();
  }
})();
